/**
 * Browser-safe structural layout projection shared by the generated runtime
 * and any design-time projection. It intentionally accepts a structural
 * version of the Project Model instead of importing it, so the browser
 * runtime remains independently bundleable.
 */

export type RuntimeContainerLayoutMode = 'fixed' | 'align-to-parent' | 'row' | 'column';
export type RuntimeLayoutItemSizingMode = 'fixed' | 'stretch' | 'fit-content';
export type RuntimeLayoutAnchor = 'start' | 'center' | 'end' | 'stretch';
export type RuntimeLayoutJustifyContent =
  'start' | 'center' | 'end' | 'space-between' | 'space-around';
export type RuntimeLayoutAlignItems = 'start' | 'center' | 'end' | 'stretch';

export interface RuntimeContainerLayout {
  readonly mode: RuntimeContainerLayoutMode;
  readonly paddingTop: number;
  readonly paddingRight: number;
  readonly paddingBottom: number;
  readonly paddingLeft: number;
  readonly gap: number;
  readonly wrap: boolean;
  readonly justifyContent: RuntimeLayoutJustifyContent;
  readonly alignItems: RuntimeLayoutAlignItems;
}

export interface RuntimeLayoutItem {
  readonly width: RuntimeLayoutItemSizingMode;
  readonly height: RuntimeLayoutItemSizingMode;
  readonly minWidth: number;
  readonly maxWidth: number | null;
  readonly minHeight: number;
  readonly maxHeight: number | null;
  readonly grow: number;
  readonly shrink: boolean;
  readonly horizontalAnchor: RuntimeLayoutAnchor;
  readonly verticalAnchor: RuntimeLayoutAnchor;
  readonly left: number;
  readonly right: number;
  readonly top: number;
  readonly bottom: number;
}

export interface RuntimeComponentLayout {
  readonly container: RuntimeContainerLayout;
  readonly item: RuntimeLayoutItem;
}

export interface RuntimeLayoutBounds {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

/** The structural subset of a component node consumed by the layout runtime. */
export interface RuntimeLayoutNode {
  readonly type?: string;
  readonly bounds: RuntimeLayoutBounds;
  readonly children?: readonly string[];
  /** Optional only to preserve mounting of pre-responsive generated models. */
  readonly layout?: RuntimeComponentLayout;
}

export interface RuntimeLayoutProjection {
  /** CSS declarations for the component as a container for its direct children. */
  readonly container: Readonly<Record<string, string>>;
  /** CSS declarations for the component as an item in its parent container. */
  readonly item: Readonly<Record<string, string>>;
}

export interface ApplyRuntimeLayoutOptions {
  /** The root owns the viewport instead of taking its legacy bounds. */
  readonly isPageRoot?: boolean;
}

const DEFAULT_CONTAINER_LAYOUT: RuntimeContainerLayout = Object.freeze({
  mode: 'fixed',
  paddingTop: 0,
  paddingRight: 0,
  paddingBottom: 0,
  paddingLeft: 0,
  gap: 0,
  wrap: false,
  justifyContent: 'start',
  alignItems: 'start',
});

const DEFAULT_LAYOUT_ITEM: RuntimeLayoutItem = Object.freeze({
  width: 'fixed',
  height: 'fixed',
  minWidth: 0,
  maxWidth: null,
  minHeight: 0,
  maxHeight: null,
  grow: 0,
  shrink: true,
  horizontalAnchor: 'start',
  verticalAnchor: 'start',
  left: 0,
  right: 0,
  top: 0,
  bottom: 0,
});

const LAYOUT_PROPERTIES = [
  'align-self',
  'bottom',
  'display',
  'flex-basis',
  'flex-direction',
  'flex-grow',
  'flex-shrink',
  'flex-wrap',
  'gap',
  'height',
  'justify-content',
  'left',
  'max-height',
  'max-width',
  'min-height',
  'min-width',
  'padding-bottom',
  'padding-left',
  'padding-right',
  'padding-top',
  'position',
  'right',
  'top',
  'translate',
  'width',
] as const;

function finite(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

function nonNegative(value: unknown, fallback: number): number {
  return Math.max(0, finite(value, fallback));
}

function pixels(value: unknown, fallback = 0): string {
  return `${String(nonNegative(value, fallback))}px`;
}

function coordinatePixels(value: unknown, fallback = 0): string {
  return `${String(finite(value, fallback))}px`;
}

function optionalPixels(value: unknown): string | undefined {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0
    ? `${String(value)}px`
    : undefined;
}

/** Resolves an absent legacy layout to the fixed-layout compatibility contract. */
export function resolveRuntimeContainerLayout(
  layout: RuntimeComponentLayout | undefined,
): RuntimeContainerLayout {
  return { ...DEFAULT_CONTAINER_LAYOUT, ...layout?.container };
}

function normalizeItem(layout: RuntimeComponentLayout | undefined): RuntimeLayoutItem {
  return { ...DEFAULT_LAYOUT_ITEM, ...layout?.item };
}

function flexAlignment(value: RuntimeLayoutAlignItems | RuntimeLayoutJustifyContent): string {
  switch (value) {
    case 'start':
      return 'flex-start';
    case 'end':
      return 'flex-end';
    default:
      return value;
  }
}

function hasContainerSemantics(
  node: RuntimeLayoutNode,
  container: RuntimeContainerLayout,
): boolean {
  return (
    node.type === 'WebPage' ||
    node.type === 'WebPanel' ||
    (node.children?.length ?? 0) > 0 ||
    container.mode !== 'fixed' ||
    container.paddingTop !== 0 ||
    container.paddingRight !== 0 ||
    container.paddingBottom !== 0 ||
    container.paddingLeft !== 0 ||
    container.gap !== 0
  );
}

function projectContainer(
  node: RuntimeLayoutNode,
  container: RuntimeContainerLayout,
): Readonly<Record<string, string>> {
  if (!hasContainerSemantics(node, container)) return {};

  const padding = {
    'padding-top': pixels(container.paddingTop),
    'padding-right': pixels(container.paddingRight),
    'padding-bottom': pixels(container.paddingBottom),
    'padding-left': pixels(container.paddingLeft),
  };

  switch (container.mode) {
    case 'row':
      return {
        position: 'relative',
        display: 'flex',
        'flex-direction': 'row',
        'flex-wrap': container.wrap ? 'wrap' : 'nowrap',
        'justify-content': flexAlignment(container.justifyContent),
        'align-items': flexAlignment(container.alignItems),
        gap: pixels(container.gap),
        ...padding,
      };
    case 'column':
      return {
        position: 'relative',
        display: 'flex',
        'flex-direction': 'column',
        'flex-wrap': container.wrap ? 'wrap' : 'nowrap',
        'justify-content': flexAlignment(container.justifyContent),
        'align-items': flexAlignment(container.alignItems),
        gap: pixels(container.gap),
        ...padding,
      };
    case 'align-to-parent':
      return { position: 'relative', ...padding };
    case 'fixed':
      // Fixed containers preserve their component's native paint styles. Padding
      // has no layout effect on their absolutely positioned children.
      return { position: 'relative' };
  }
}

function minMaxStyles(item: RuntimeLayoutItem): Readonly<Record<string, string>> {
  const maxWidth = optionalPixels(item.maxWidth);
  const maxHeight = optionalPixels(item.maxHeight);
  return {
    'min-width': pixels(item.minWidth),
    'min-height': pixels(item.minHeight),
    ...(maxWidth === undefined ? {} : { 'max-width': maxWidth }),
    ...(maxHeight === undefined ? {} : { 'max-height': maxHeight }),
  };
}

function fixedItemStyles(
  node: RuntimeLayoutNode,
  item: RuntimeLayoutItem,
): Readonly<Record<string, string>> {
  return {
    position: 'absolute',
    left: coordinatePixels(node.bounds.x),
    top: coordinatePixels(node.bounds.y),
    width: pixels(node.bounds.width),
    height: pixels(node.bounds.height),
    ...minMaxStyles(item),
  };
}

interface AxisProjection {
  readonly styles: Readonly<Record<string, string>>;
  readonly centeredFitContent: boolean;
}

function alignAxis(
  axis: 'horizontal' | 'vertical',
  size: RuntimeLayoutItemSizingMode,
  anchor: RuntimeLayoutAnchor,
  before: number,
  after: number,
  fixedSize: number,
): AxisProjection {
  const start = axis === 'horizontal' ? 'left' : 'top';
  const end = axis === 'horizontal' ? 'right' : 'bottom';
  const dimension = axis === 'horizontal' ? 'width' : 'height';
  const shouldStretch = size === 'stretch' || anchor === 'stretch';

  if (shouldStretch) {
    return {
      styles: { [start]: coordinatePixels(before), [end]: coordinatePixels(after) },
      centeredFitContent: false,
    };
  }

  const dimensionStyle =
    size === 'fixed' ? { [dimension]: pixels(fixedSize) } : { [dimension]: 'fit-content' };
  switch (anchor) {
    case 'end':
      return {
        styles: { [end]: coordinatePixels(after), ...dimensionStyle },
        centeredFitContent: false,
      };
    case 'center':
      if (size === 'fixed') {
        return {
          styles: {
            [start]: `calc(50% + ${coordinatePixels(before)} - ${pixels(fixedSize / 2)})`,
            ...dimensionStyle,
          },
          centeredFitContent: false,
        };
      }
      return {
        styles: { [start]: `calc(50% + ${coordinatePixels(before)})`, ...dimensionStyle },
        centeredFitContent: true,
      };
    case 'start':
      return {
        styles: { [start]: coordinatePixels(before), ...dimensionStyle },
        centeredFitContent: false,
      };
  }
}

function alignedItemStyles(
  node: RuntimeLayoutNode,
  item: RuntimeLayoutItem,
): Readonly<Record<string, string>> {
  const horizontal = alignAxis(
    'horizontal',
    item.width,
    item.horizontalAnchor,
    item.left,
    item.right,
    node.bounds.width,
  );
  const vertical = alignAxis(
    'vertical',
    item.height,
    item.verticalAnchor,
    item.top,
    item.bottom,
    node.bounds.height,
  );
  return {
    position: 'absolute',
    ...horizontal.styles,
    ...vertical.styles,
    ...(horizontal.centeredFitContent || vertical.centeredFitContent
      ? {
          translate: `${horizontal.centeredFitContent ? '-50%' : '0'} ${
            vertical.centeredFitContent ? '-50%' : '0'
          }`,
        }
      : {}),
    ...minMaxStyles(item),
  };
}

function flowItemStyles(
  node: RuntimeLayoutNode,
  parentMode: 'row' | 'column',
  item: RuntimeLayoutItem,
): Readonly<Record<string, string>> {
  const isRow = parentMode === 'row';
  const mainSize = isRow ? item.width : item.height;
  const crossSize = isRow ? item.height : item.width;
  const mainDimension = isRow ? 'width' : 'height';
  const crossDimension = isRow ? 'height' : 'width';
  const mainBounds = isRow ? node.bounds.width : node.bounds.height;
  const crossBounds = isRow ? node.bounds.height : node.bounds.width;
  const mainGrow =
    mainSize === 'stretch' ? Math.max(1, nonNegative(item.grow, 0)) : nonNegative(item.grow, 0);

  const mainStyles: Readonly<Record<string, string>> =
    mainSize === 'fixed'
      ? { [mainDimension]: pixels(mainBounds), 'flex-basis': pixels(mainBounds) }
      : mainSize === 'stretch'
        ? { [mainDimension]: 'auto', 'flex-basis': '0px' }
        : { [mainDimension]: 'fit-content', 'flex-basis': 'fit-content' };
  const crossStyles: Readonly<Record<string, string>> =
    crossSize === 'fixed'
      ? { [crossDimension]: pixels(crossBounds) }
      : crossSize === 'stretch'
        ? { [crossDimension]: 'auto', 'align-self': 'stretch' }
        : { [crossDimension]: 'fit-content' };

  return {
    position: 'relative',
    'flex-grow': String(mainGrow),
    'flex-shrink': item.shrink ? '1' : '0',
    ...mainStyles,
    ...crossStyles,
    ...minMaxStyles(item),
  };
}

function projectItem(
  node: RuntimeLayoutNode,
  parent: RuntimeContainerLayout | undefined,
): Readonly<Record<string, string>> {
  const item = normalizeItem(node.layout);
  const mode = parent?.mode ?? 'fixed';
  switch (mode) {
    case 'align-to-parent':
      return alignedItemStyles(node, item);
    case 'row':
    case 'column':
      return flowItemStyles(node, mode, item);
    case 'fixed':
      return fixedItemStyles(node, item);
  }
}

/**
 * Converts persisted layout rules to browser CSS. The result is pure and can
 * also be used by a design-time renderer to mirror generated-runtime layout.
 */
export function projectRuntimeLayout(
  node: RuntimeLayoutNode,
  parentContainer?: RuntimeContainerLayout,
): RuntimeLayoutProjection {
  const container = resolveRuntimeContainerLayout(node.layout);
  return {
    container: projectContainer(node, container),
    item: projectItem(node, parentContainer),
  };
}

function setImportantStyles(element: HTMLElement, styles: Readonly<Record<string, string>>): void {
  for (const property of LAYOUT_PROPERTIES) element.style.removeProperty(property);
  const display = styles.display;
  if (display === undefined) delete element.dataset.webradLayoutDisplay;
  else element.dataset.webradLayoutDisplay = display;
  for (const [property, value] of Object.entries(styles)) {
    // `hidden` is part of the public component API. Keep the structural
    // display value in data for show(), but never let it reveal a hidden node.
    if (property === 'display' && element.hidden) continue;
    element.style.setProperty(property, value, 'important');
  }
  if (element.hidden) element.style.setProperty('display', 'none', 'important');
}

/**
 * Applies structural layout declarations with inline `!important` precedence.
 * Reusable visual styles are intentionally unable to move or resize an
 * instance; the Project Model's instance layout remains authoritative.
 */
export function applyRuntimeLayout(
  element: HTMLElement,
  node: RuntimeLayoutNode,
  parentContainer?: RuntimeContainerLayout,
  options: ApplyRuntimeLayoutOptions = {},
): RuntimeLayoutProjection {
  const projection = projectRuntimeLayout(node, parentContainer);
  const rootStyles = options.isPageRoot
    ? {
        position: 'relative',
        width: '100vw',
        height: '100dvh',
        'min-height': '100dvh',
      }
    : projection.item;
  setImportantStyles(element, { ...projection.container, ...rootStyles });
  return projection;
}

render.ts:
import type { WebComponent } from './component.js';
import {
  WebButton,
  WebCheckBox,
  WebComboBox,
  WebEdit,
  WebImage,
  WebLabel,
  WebListBox,
  WebPanel,
  WebTextArea,
  type WebImageObjectFit,
  type WebInputType,
  type WebSelectItem,
} from './controls.js';
import { WebPage } from './page.js';
import {
  applyRuntimeLayout,
  resolveRuntimeContainerLayout,
  type RuntimeComponentLayout,
  type RuntimeContainerLayout,
} from './layout.js';
import {
  projectComponentVisual,
  readBooleanProperty,
  readIntegerProperty,
  readStringProperty,
  tokenizeTailwindClasses,
} from './visual.js';

export interface RuntimeBounds {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export interface RuntimeComponentNode {
  readonly id: string;
  readonly type: string;
  readonly name: string;
  readonly parentId: string | null;
  /** Instance-owned responsive layout. */
  readonly layout: RuntimeComponentLayout;
  readonly bounds: RuntimeBounds;
  readonly props: Readonly<Record<string, unknown>>;
  readonly children: readonly string[];
  /** Resolved at compile time so generated apps do not ship a Tailwind runtime. */
  readonly styleClassName?: string;
}

export interface RuntimePageModel {
  readonly id: string;
  readonly name: string;
  readonly caption: string;
  readonly width: number;
  readonly height: number;
  readonly components: readonly RuntimeComponentNode[];
  readonly rootComponentId: string;
}

export interface RuntimeComponentAdapter<T extends WebComponent = WebComponent> {
  readonly createElement: (document: Document, node: RuntimeComponentNode) => HTMLElement;
  readonly createComponent: (element: HTMLElement) => T;
  readonly applyProperties?: (component: T, node: RuntimeComponentNode) => void;
}

function inputElement(element: HTMLElement): HTMLInputElement {
  if (!(element instanceof HTMLInputElement)) throw new TypeError('Expected an input element.');
  return element;
}

function buttonElement(element: HTMLElement): HTMLButtonElement {
  if (!(element instanceof HTMLButtonElement)) throw new TypeError('Expected a button element.');
  return element;
}

function textAreaElement(element: HTMLElement): HTMLTextAreaElement {
  if (!(element instanceof HTMLTextAreaElement))
    throw new TypeError('Expected a textarea element.');
  return element;
}

function selectElement(element: HTMLElement): HTMLSelectElement {
  if (!(element instanceof HTMLSelectElement)) throw new TypeError('Expected a select element.');
  return element;
}

function imageElement(element: HTMLElement): HTMLImageElement {
  if (!(element instanceof HTMLImageElement)) throw new TypeError('Expected an image element.');
  return element;
}

function selectItems(node: RuntimeComponentNode): readonly (string | WebSelectItem)[] {
  const items = node.props.items;
  if (!Array.isArray(items)) return [];
  return items.flatMap((item): readonly (string | WebSelectItem)[] => {
    if (typeof item === 'string') return [item];
    if (typeof item !== 'object' || item === null) return [];
    const value = Reflect.get(item, 'value');
    const label = Reflect.get(item, 'label');
    const disabled = Reflect.get(item, 'disabled');
    if (typeof value !== 'string' || typeof label !== 'string') return [];
    return [{ value, label, disabled: typeof disabled === 'boolean' ? disabled : undefined }];
  });
}

export class RuntimeComponentRegistry {
  readonly #adapters = new Map<string, RuntimeComponentAdapter>();

  public register<T extends WebComponent>(type: string, adapter: RuntimeComponentAdapter<T>): this {
    if (this.#adapters.has(type))
      throw new Error(`Runtime component "${type}" is already registered.`);
    const applyProperties = adapter.applyProperties;
    this.#adapters.set(type, {
      createElement: adapter.createElement,
      createComponent: adapter.createComponent,
      applyProperties:
        applyProperties === undefined
          ? undefined
          : (component, node) => {
              applyProperties(component as T, node);
            },
    });
    return this;
  }

  public has(type: string): boolean {
    return this.#adapters.has(type);
  }

  public require(type: string): RuntimeComponentAdapter {
    const adapter = this.#adapters.get(type);
    if (adapter === undefined) throw new Error(`No runtime adapter is registered for "${type}".`);
    return adapter;
  }

  public create(document: Document, node: RuntimeComponentNode): WebComponent {
    const adapter = this.require(node.type);
    const element = adapter.createElement(document, node);
    const component = adapter.createComponent(element);
    adapter.applyProperties?.(component, node);
    return component;
  }
}

function applyCommon(component: WebComponent, node: RuntimeComponentNode): void {
  const { element } = component;
  const visual = projectComponentVisual(node);
  element.dataset.webradId = node.id;
  element.dataset.webradName = node.name;
  element.dataset.webradType = node.type;
  element.classList.add(
    ...visual.classNames,
    ...tokenizeTailwindClasses(node.styleClassName ?? ''),
  );
  component.width = node.bounds.width;
  component.height = node.bounds.height;
  // A selected Tailwind style owns paint properties. The structural layout is
  // applied after the hierarchy exists, when each child can read its parent's
  // persisted container mode.
  if (node.styleClassName === undefined) {
    component.backgroundColor = visual.style.backgroundColor ?? '';
    component.color = visual.style.color ?? '';
    component.borderColor = visual.style.borderColor ?? '';
    element.style.borderStyle = visual.style.borderStyle ?? '';
    element.style.borderWidth = visual.style.borderWidth ?? '';
  }
  if (node.parentId !== null) {
    // Preserve the historic registry.create() behavior for callers that create
    // a standalone node. mountPage() replaces this legacy fallback with the
    // responsive projection below.
    element.style.position = 'absolute';
    component.x = node.bounds.x;
    component.y = node.bounds.y;
  }
  component.visible = visual.visible;
  component.enabled = visual.enabled;
  if (visual.tabIndex !== undefined) component.tabIndex = visual.tabIndex;
  if (visual.title !== undefined) element.title = visual.title;
}

function elementFactory(tagName: string): RuntimeComponentAdapter['createElement'] {
  return (document) => document.createElement(tagName);
}

export const runtimeComponentRegistry = new RuntimeComponentRegistry();

runtimeComponentRegistry
  .register<WebPage>('WebPage', {
    createElement: elementFactory('section'),
    createComponent: (element) => new WebPage(element),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.element.setAttribute('role', 'application');
      component.caption = readStringProperty(node, 'caption', node.name);
    },
  })
  .register<WebPanel>('WebPanel', {
    createElement: elementFactory('div'),
    createComponent: (element) => new WebPanel(element),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.caption = readStringProperty(node, 'caption');
    },
  })
  .register<WebLabel>('WebLabel', {
    createElement: elementFactory('span'),
    createComponent: (element) => new WebLabel(element),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.caption = readStringProperty(
        node,
        'caption',
        readStringProperty(node, 'text', node.name),
      );
      component.autoSize = readBooleanProperty(node, 'autoSize');
    },
  })
  .register<WebEdit>('WebEdit', {
    createElement: (document) => {
      const element = document.createElement('input');
      element.type = 'text';
      return element;
    },
    createComponent: (element) => new WebEdit(inputElement(element)),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.value = readStringProperty(node, 'value');
      component.placeholder = readStringProperty(node, 'placeholder');
      component.readOnly = readBooleanProperty(node, 'readOnly');
      component.inputType = readStringProperty(node, 'inputType', 'text') as WebInputType;
    },
  })
  .register<WebTextArea>('WebTextArea', {
    createElement: elementFactory('textarea'),
    createComponent: (element) => new WebTextArea(textAreaElement(element)),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.value = readStringProperty(node, 'value');
      component.placeholder = readStringProperty(node, 'placeholder');
      component.readOnly = readBooleanProperty(node, 'readOnly');
      const rows = readIntegerProperty(node, 'rows');
      if (rows !== undefined && rows > 0) {
        component.rows = rows;
      }
    },
  })
  .register<WebButton>('WebButton', {
    createElement: (document) => {
      const element = document.createElement('button');
      element.type = 'button';
      return element;
    },
    createComponent: (element) => new WebButton(buttonElement(element)),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.caption = readStringProperty(node, 'caption', node.name);
    },
  })
  .register<WebCheckBox>('WebCheckBox', {
    createElement: (document) => {
      const label = document.createElement('label');
      const input = document.createElement('input');
      input.type = 'checkbox';
      const caption = document.createElement('span');
      caption.dataset.webradCheckboxCaption = '';
      label.append(input, caption);
      return label;
    },
    createComponent: (element) => new WebCheckBox(element),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.caption = readStringProperty(node, 'caption', node.name);
      component.checked = readBooleanProperty(node, 'checked');
    },
  })
  .register<WebComboBox>('WebComboBox', {
    createElement: elementFactory('select'),
    createComponent: (element) => new WebComboBox(selectElement(element)),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.items = selectItems(node);
      const selectedIndex = readIntegerProperty(node, 'selectedIndex');
      if (selectedIndex !== undefined) {
        component.selectedIndex = selectedIndex;
      } else {
        component.value = readStringProperty(node, 'value');
      }
    },
  })
  .register<WebImage>('WebImage', {
    createElement: elementFactory('img'),
    createComponent: (element) => new WebImage(imageElement(element)),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.src = readStringProperty(node, 'src');
      component.alt = readStringProperty(node, 'alt', node.name);
      if (node.styleClassName === undefined) {
        const objectFit = readStringProperty(node, 'objectFit');
        if (objectFit.length > 0) component.objectFit = objectFit as WebImageObjectFit;
      }
    },
  })
  .register<WebListBox>('WebListBox', {
    createElement: (document) => {
      const element = document.createElement('select');
      element.size = 4;
      return element;
    },
    createComponent: (element) => new WebListBox(selectElement(element)),
    applyProperties: (component, node) => {
      applyCommon(component, node);
      component.items = selectItems(node);
      component.multiple = readBooleanProperty(node, 'multiple');
      const selectedIndex = readIntegerProperty(node, 'selectedIndex');
      if (selectedIndex !== undefined) {
        component.selectedIndex = selectedIndex;
      } else {
        component.value = readStringProperty(node, 'value');
      }
    },
  });

export interface MountedRuntimePage {
  readonly element: HTMLElement;
  readonly page: WebPage;
  readonly components: ReadonlyMap<string, WebComponent>;
}

export interface MountPageOptions {
  readonly replaceHostContents?: boolean;
  readonly registry?: RuntimeComponentRegistry;
}

export function mountPage(
  model: RuntimePageModel,
  host: HTMLElement = document.body,
  options: MountPageOptions = {},
): MountedRuntimePage {
  const registry = options.registry ?? runtimeComponentRegistry;
  const nodes = new Map(model.components.map((node) => [node.id, node]));
  const components = new Map<string, WebComponent>();

  const createBranch = (nodeId: string): HTMLElement => {
    const node = nodes.get(nodeId);
    if (node === undefined)
      throw new Error(`Runtime page references unknown component "${nodeId}".`);
    const component = registry.create(host.ownerDocument, node);
    components.set(node.id, component);
    for (const childId of node.children) component.element.append(createBranch(childId));
    return component.element;
  };

  const rootElement = createBranch(model.rootComponentId);
  const rootComponent = components.get(model.rootComponentId);
  if (!(rootComponent instanceof WebPage))
    throw new Error('The runtime root component must be WebPage.');
  rootComponent.width = model.width;
  rootComponent.height = model.height;
  rootComponent.caption = model.caption;

  const applyBranchLayout = (
    nodeId: string,
    parentContainer: RuntimeContainerLayout | undefined,
    isPageRoot = false,
  ): void => {
    const node = nodes.get(nodeId);
    const component = components.get(nodeId);
    if (node === undefined || component === undefined) {
      throw new Error(`Runtime page layout references unknown component "${nodeId}".`);
    }
    applyRuntimeLayout(component.element, node, parentContainer, { isPageRoot });
    const container = resolveRuntimeContainerLayout(node.layout);
    for (const childId of node.children) applyBranchLayout(childId, container);
  };
  applyBranchLayout(model.rootComponentId, undefined, true);
  rootElement.dataset.webradLayout = resolveRuntimeContainerLayout(
    nodes.get(model.rootComponentId)?.layout,
  ).mode;

  rootElement.dataset.webradPageId = model.id;
  if (options.replaceHostContents ?? true) host.replaceChildren(rootElement);
  else host.append(rootElement);
  return { element: rootElement, page: rootComponent, components };
}

visual.ts:
/**
 * Browser-safe visual contract shared by the generated runtime and design-time
 * projections. Layout positioning and designer interaction intentionally stay
 * outside this module.
 */
export interface VisualPropertySource {
  readonly props: Readonly<Record<string, unknown>>;
}

export interface VisualComponentSource extends VisualPropertySource {
  readonly type: string;
  readonly bounds: {
    readonly width: number;
    readonly height: number;
  };
}

/** Browser-safe structural counterpart of the versioned project style model. */
export type ComponentStyleStateName = 'base' | 'hover' | 'focus' | 'active' | 'disabled';
export type StyleLengthUnit = 'px' | 'rem' | '%' | 'vw' | 'vh';

export interface StyleLengthValue {
  readonly value: number;
  readonly unit: StyleLengthUnit;
}

export type LinearGradientDirection =
  | 'to-right'
  | 'to-bottom-right'
  | 'to-bottom'
  | 'to-bottom-left'
  | 'to-left'
  | 'to-top-left'
  | 'to-top'
  | 'to-top-right';

/** Browser-safe counterpart of the validated project-model gradient value. */
export interface BackgroundGradientValue {
  readonly kind: 'linear';
  readonly direction: LinearGradientDirection;
  readonly from: string;
  readonly to: string;
}

export type StylePropertyValue = string | number | StyleLengthValue | BackgroundGradientValue;
export type TailwindStyleProperties = Readonly<Record<string, StylePropertyValue | undefined>>;

export interface TailwindStyleSource {
  readonly states: Readonly<Record<ComponentStyleStateName, TailwindStyleProperties>>;
}

/**
 * Splits a Tailwind class expression while understanding arbitrary values,
 * functions and quotes. Internal whitespace is normalized to Tailwind's `_`
 * representation so every result is a valid DOM class token.
 */
export function tokenizeTailwindClasses(value: string): readonly string[] {
  const tokens: string[] = [];
  let token = '';
  let quote: "'" | '"' | '`' | undefined;
  let escaped = false;
  const delimiters: string[] = [];
  const closingDelimiter: Readonly<Record<string, string>> = {
    '[': ']',
    '(': ')',
    '{': '}',
  };

  const commit = (): void => {
    // A DOM class token cannot contain whitespace. Tailwind uses underscores to
    // represent spaces inside arbitrary values (for example content strings).
    const normalized = token.trim().replace(/\s+/gu, '_');
    if (normalized.length > 0) tokens.push(normalized);
    token = '';
  };

  for (const character of value) {
    if (escaped) {
      token += character;
      escaped = false;
      continue;
    }
    if (character === '\\') {
      token += character;
      escaped = true;
      continue;
    }
    if (quote !== undefined) {
      token += character;
      if (character === quote) quote = undefined;
      continue;
    }
    if (character === "'" || character === '"' || character === '`') {
      token += character;
      quote = character;
      continue;
    }
    const closing = closingDelimiter[character];
    if (closing !== undefined) {
      token += character;
      delimiters.push(closing);
      continue;
    }
    if (delimiters.at(-1) === character) {
      token += character;
      delimiters.pop();
      continue;
    }
    if (/\s/u.test(character) && delimiters.length === 0) {
      commit();
      continue;
    }
    token += character;
  }
  commit();
  return tokens;
}

function isStyleLengthValue(value: unknown): value is StyleLengthValue {
  return (
    typeof value === 'object' &&
    value !== null &&
    'value' in value &&
    typeof value.value === 'number' &&
    Number.isFinite(value.value) &&
    Math.abs(value.value) <= 1_000_000 &&
    'unit' in value &&
    (value.unit === 'px' ||
      value.unit === 'rem' ||
      value.unit === '%' ||
      value.unit === 'vw' ||
      value.unit === 'vh')
  );
}

const LINEAR_GRADIENT_DIRECTIONS: ReadonlySet<LinearGradientDirection> = new Set([
  'to-right',
  'to-bottom-right',
  'to-bottom',
  'to-bottom-left',
  'to-left',
  'to-top-left',
  'to-top',
  'to-top-right',
]);

function isBackgroundGradientValue(value: unknown): value is BackgroundGradientValue {
  return (
    typeof value === 'object' &&
    value !== null &&
    'kind' in value &&
    value.kind === 'linear' &&
    'direction' in value &&
    typeof value.direction === 'string' &&
    LINEAR_GRADIENT_DIRECTIONS.has(value.direction as LinearGradientDirection) &&
    'from' in value &&
    typeof value.from === 'string' &&
    /^#[\da-f]{6}$/iu.test(value.from) &&
    'to' in value &&
    typeof value.to === 'string' &&
    /^#[\da-f]{6}$/iu.test(value.to)
  );
}

function finiteNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function stringValue(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

function formatNumber(value: number): string {
  return Object.is(value, -0) ? '0' : String(value);
}

function lengthClass(prefix: string, value: unknown, important = false): string | undefined {
  const suffix = important ? '!' : '';
  if (typeof value === 'string' && /^[a-z0-9][a-z0-9-]*$/u.test(value)) {
    return `${prefix}-${value}${suffix}`;
  }
  if (!isStyleLengthValue(value)) return undefined;
  return `${prefix}-[${formatNumber(value.value)}${value.unit}]${suffix}`;
}

function percentageFractionClass(prefix: string, value: unknown): string | undefined {
  const number = finiteNumber(value);
  return number === undefined ? undefined : `${prefix}-[${formatNumber(number / 100)}]`;
}

function degreeClass(prefix: string, value: unknown): string | undefined {
  const number = finiteNumber(value);
  return number === undefined ? undefined : `${prefix}-[${formatNumber(number)}deg]`;
}

function millisecondsClass(prefix: string, value: unknown): string | undefined {
  const number = finiteNumber(value);
  return number === undefined ? undefined : `${prefix}-[${formatNumber(number)}ms]`;
}

function prefixedEnumClass(prefix: string, value: unknown): string | undefined {
  const name = stringValue(value);
  return name === undefined ? undefined : `${prefix}-${name}`;
}

function mappedEnumClass(
  value: unknown,
  values: Readonly<Record<string, string>>,
): string | undefined {
  const name = stringValue(value);
  return name === undefined ? undefined : values[name];
}

function colorClass(prefix: string, value: unknown): string | undefined {
  if (typeof value !== 'string') return undefined;
  if (value === 'current') return `${prefix}-current`;
  if (value === 'transparent' || value === 'inherit') return `${prefix}-${value}`;
  return /^#(?:[\da-f]{3,4}|[\da-f]{6}|[\da-f]{8})$/iu.test(value)
    ? `${prefix}-[${value}]`
    : undefined;
}

function backgroundGradientClass(value: unknown): string | undefined {
  if (!isBackgroundGradientValue(value)) return undefined;
  const direction = value.direction.replaceAll('-', '_');
  return `bg-[linear-gradient(${direction},${value.from.toLowerCase()},${value.to.toLowerCase()})]`;
}

const FLEX_DIRECTION_CLASSES: Readonly<Record<string, string>> = {
  row: 'flex-row',
  'row-reverse': 'flex-row-reverse',
  column: 'flex-col',
  'column-reverse': 'flex-col-reverse',
};

const FLEX_WRAP_CLASSES: Readonly<Record<string, string>> = {
  nowrap: 'flex-nowrap',
  wrap: 'flex-wrap',
  'wrap-reverse': 'flex-wrap-reverse',
};

const TEXT_TRANSFORM_CLASSES: Readonly<Record<string, string>> = {
  none: 'normal-case',
  uppercase: 'uppercase',
  lowercase: 'lowercase',
  capitalize: 'capitalize',
};

const TEXT_DECORATION_CLASSES: Readonly<Record<string, string>> = {
  none: 'no-underline',
  underline: 'underline',
  overline: 'overline',
  lineThrough: 'line-through',
};

const FONT_STYLE_CLASSES: Readonly<Record<string, string>> = {
  normal: 'not-italic',
  italic: 'italic',
};

const WHITE_SPACE_CLASSES: Readonly<Record<string, string>> = {
  normal: 'whitespace-normal',
  nowrap: 'whitespace-nowrap',
  pre: 'whitespace-pre',
  preLine: 'whitespace-pre-line',
  preWrap: 'whitespace-pre-wrap',
  breakSpaces: 'whitespace-break-spaces',
};

const TIMING_CLASSES: Readonly<Record<string, string>> = {
  linear: 'ease-linear',
  easeIn: 'ease-in',
  easeOut: 'ease-out',
  easeInOut: 'ease-in-out',
};

const ANIMATION_TIMING_VALUES: Readonly<Record<string, string>> = {
  linear: 'linear',
  easeIn: 'ease-in',
  easeOut: 'ease-out',
  easeInOut: 'ease-in-out',
};

const ANIMATION_ITERATIONS: Readonly<Record<string, string>> = {
  once: '1',
  twice: '2',
  three: '3',
  infinite: 'infinite',
};

/** Converts one validated visual property to its exact Tailwind v4 candidate. */
export function resolveStylePropertyCandidate(
  propertyName: string,
  value: StylePropertyValue,
): string | undefined {
  switch (propertyName) {
    case 'display':
      return stringValue(value);
    case 'overflow':
      return prefixedEnumClass('overflow', value);
    case 'flexDirection':
      return mappedEnumClass(value, FLEX_DIRECTION_CLASSES);
    case 'flexWrap':
      return mappedEnumClass(value, FLEX_WRAP_CLASSES);
    case 'justifyContent':
      return prefixedEnumClass('justify', value);
    case 'alignItems':
      return prefixedEnumClass('items', value);
    case 'alignContent':
      return prefixedEnumClass('content', value);
    case 'gridColumns': {
      const number = finiteNumber(value);
      return number === undefined || !Number.isInteger(number)
        ? undefined
        : `grid-cols-${formatNumber(number)}`;
    }
    case 'gridRows': {
      const number = finiteNumber(value);
      return number === undefined || !Number.isInteger(number)
        ? undefined
        : `grid-rows-${formatNumber(number)}`;
    }
    case 'gap':
      return lengthClass('gap', value);
    case 'rowGap':
      return lengthClass('gap-y', value);
    case 'columnGap':
      return lengthClass('gap-x', value);
    case 'width':
      return lengthClass('w', value, true);
    case 'height':
      return lengthClass('h', value, true);
    case 'minWidth':
      return lengthClass('min-w', value, true);
    case 'maxWidth':
      return lengthClass('max-w', value, true);
    case 'minHeight':
      return lengthClass('min-h', value, true);
    case 'maxHeight':
      return lengthClass('max-h', value, true);
    case 'marginTop':
      return lengthClass('mt', value);
    case 'marginRight':
      return lengthClass('mr', value);
    case 'marginBottom':
      return lengthClass('mb', value);
    case 'marginLeft':
      return lengthClass('ml', value);
    case 'paddingTop':
      return lengthClass('pt', value);
    case 'paddingRight':
      return lengthClass('pr', value);
    case 'paddingBottom':
      return lengthClass('pb', value);
    case 'paddingLeft':
      return lengthClass('pl', value);
    case 'fontFamily':
      return prefixedEnumClass('font', value);
    case 'fontSize':
      return lengthClass('text', value);
    case 'fontWeight':
      return prefixedEnumClass('font', value);
    case 'lineHeight':
      return lengthClass('leading', value);
    case 'letterSpacing':
      return lengthClass('tracking', value);
    case 'textAlign':
      return prefixedEnumClass('text', value);
    case 'textTransform':
      return mappedEnumClass(value, TEXT_TRANSFORM_CLASSES);
    case 'textDecoration':
      return mappedEnumClass(value, TEXT_DECORATION_CLASSES);
    case 'fontStyle':
      return mappedEnumClass(value, FONT_STYLE_CLASSES);
    case 'whiteSpace':
      return mappedEnumClass(value, WHITE_SPACE_CLASSES);
    case 'textColor':
      return colorClass('text', value);
    case 'backgroundColor':
      return colorClass('bg', value);
    case 'backgroundGradient':
      return backgroundGradientClass(value);
    case 'borderWidth':
      return lengthClass('border', value);
    case 'borderStyle':
      return prefixedEnumClass('border', value);
    case 'borderColor':
      return colorClass('border', value);
    case 'borderRadius':
      return lengthClass('rounded', value);
    case 'outlineWidth':
      return lengthClass('outline', value);
    case 'outlineStyle':
      return prefixedEnumClass('outline', value);
    case 'outlineColor':
      return colorClass('outline', value);
    case 'outlineOffset':
      return lengthClass('outline-offset', value);
    case 'ringWidth':
      return lengthClass('ring', value);
    case 'ringColor':
      return colorClass('ring', value);
    case 'ringOffsetWidth':
      return lengthClass('ring-offset', value);
    case 'ringOffsetColor':
      return colorClass('ring-offset', value);
    case 'boxShadow':
      return prefixedEnumClass('shadow', value);
    case 'opacity':
      return percentageFractionClass('opacity', value);
    case 'blur':
      return lengthClass('blur', value);
    case 'brightness':
      return percentageFractionClass('brightness', value);
    case 'contrast':
      return percentageFractionClass('contrast', value);
    case 'grayscale':
      return percentageFractionClass('grayscale', value);
    case 'saturate':
      return percentageFractionClass('saturate', value);
    case 'translateX':
      return lengthClass('translate-x', value);
    case 'translateY':
      return lengthClass('translate-y', value);
    case 'scale':
      return percentageFractionClass('scale', value);
    case 'rotate':
      return degreeClass('rotate', value);
    case 'skewX':
      return degreeClass('skew-x', value);
    case 'skewY':
      return degreeClass('skew-y', value);
    case 'transformOrigin':
      return prefixedEnumClass('origin', value);
    case 'transitionProperty':
      return prefixedEnumClass('transition', value);
    case 'transitionDuration':
      return millisecondsClass('duration', value);
    case 'transitionDelay':
      return millisecondsClass('delay', value);
    case 'transitionTimingFunction':
      return mappedEnumClass(value, TIMING_CLASSES);
    case 'animationName':
      return prefixedEnumClass('animate', value);
    case 'animationDuration': {
      const number = finiteNumber(value);
      return number === undefined ? undefined : `[animation-duration:${formatNumber(number)}ms]!`;
    }
    case 'animationIterationCount': {
      const name = stringValue(value);
      const count = name === undefined ? undefined : ANIMATION_ITERATIONS[name];
      return count === undefined ? undefined : `[animation-iteration-count:${count}]!`;
    }
    case 'animationTimingFunction': {
      const name = stringValue(value);
      const timing = name === undefined ? undefined : ANIMATION_TIMING_VALUES[name];
      return timing === undefined ? undefined : `[animation-timing-function:${timing}]!`;
    }
    case 'cursor':
      return prefixedEnumClass('cursor', value);
    case 'userSelect':
      return prefixedEnumClass('select', value);
    case 'pointerEvents':
      return prefixedEnumClass('pointer-events', value);
    case 'objectFit':
    case 'objectPosition':
      return prefixedEnumClass('object', value);
    default:
      return undefined;
  }
}

/** Returns raw candidates for a single state, preserving metadata order from the model object. */
export function resolveComponentStyleStateClassNames(
  properties: TailwindStyleProperties | null | undefined,
): readonly string[] {
  if (properties === undefined || properties === null || typeof properties !== 'object') return [];
  const resolved: string[] = [];
  const seen = new Set<string>();
  for (const [propertyName, value] of Object.entries(properties)) {
    if (value === undefined) continue;
    const candidate = resolveStylePropertyCandidate(propertyName, value);
    if (candidate === undefined || seen.has(candidate)) continue;
    seen.add(candidate);
    resolved.push(candidate);
  }
  return resolved;
}

function stateProperties(
  style: TailwindStyleSource | null | undefined,
  stateName: ComponentStyleStateName,
): TailwindStyleProperties | undefined {
  if (style === undefined || style === null || typeof style.states !== 'object') return undefined;
  const properties: unknown = style.states[stateName];
  return typeof properties === 'object' && properties !== null
    ? (properties as TailwindStyleProperties)
    : undefined;
}

/** Resolves the exact real-state class candidates applied to a styled component. */
export function resolveComponentStyleClassNames(
  style: TailwindStyleSource | null | undefined,
): readonly string[] {
  const resolved: string[] = [];
  const seen = new Set<string>();
  const appendState = (stateName: ComponentStyleStateName, variants: readonly string[]): void => {
    for (const candidate of resolveComponentStyleStateClassNames(
      stateProperties(style, stateName),
    )) {
      for (const variant of variants) {
        const className = variant.length === 0 ? candidate : `${variant}:${candidate}`;
        if (seen.has(className)) continue;
        seen.add(className);
        resolved.push(className);
      }
    }
  };

  appendState('base', ['']);
  appendState('hover', ['hover']);
  // focus-within supports compound controls such as WebCheckBox.
  appendState('focus', ['focus', 'focus-within']);
  appendState('active', ['active']);
  // Every visual root exposes aria-disabled; native controls also expose :disabled.
  appendState('disabled', ['disabled', 'aria-disabled']);
  return resolved;
}

export function resolveComponentStyleClassName(
  style: TailwindStyleSource | null | undefined,
): string {
  return resolveComponentStyleClassNames(style).join(' ');
}

/**
 * Resolves the forced Designer preview. The selected state overrides base by
 * property before candidates are generated, so CSS source order cannot make a
 * base value win accidentally.
 */
export function resolveComponentStylePreviewClassName(
  style: TailwindStyleSource | null | undefined,
  stateName: ComponentStyleStateName,
): string {
  const base = stateProperties(style, 'base') ?? {};
  const selected = stateName === 'base' ? {} : (stateProperties(style, stateName) ?? {});
  return resolveComponentStyleStateClassNames({ ...base, ...selected }).join(' ');
}

export type VisualSizingMode = 'bounds' | 'fill';

export interface ComponentVisualStyle {
  readonly width: string;
  readonly height: string;
  readonly backgroundColor?: string;
  readonly color?: string;
  readonly borderColor?: string;
  readonly borderStyle?: 'solid';
  readonly borderWidth?: string;
}

export interface ComponentVisualProjection {
  readonly classNames: readonly [base: 'wr-component', type: string];
  readonly style: ComponentVisualStyle;
  readonly visible: boolean;
  readonly enabled: boolean;
  readonly title?: string;
  readonly tabIndex?: number;
}

export function readStringProperty(
  source: VisualPropertySource,
  name: string,
  fallback = '',
): string {
  const value = source.props[name];
  return typeof value === 'string' ? value : fallback;
}

export function readBooleanProperty(
  source: VisualPropertySource,
  name: string,
  fallback = false,
): boolean {
  const value = source.props[name];
  return typeof value === 'boolean' ? value : fallback;
}

export function readIntegerProperty(source: VisualPropertySource, name: string): number | undefined;
export function readIntegerProperty(
  source: VisualPropertySource,
  name: string,
  fallback: number,
): number;
export function readIntegerProperty(
  source: VisualPropertySource,
  name: string,
  fallback?: number,
): number | undefined {
  const value = source.props[name];
  return typeof value === 'number' && Number.isInteger(value) ? value : fallback;
}

export function readStringListProperty(
  source: VisualPropertySource,
  name: string,
): readonly string[] {
  const value = source.props[name];
  return Array.isArray(value) && value.every((item) => typeof item === 'string') ? value : [];
}

export function projectComponentVisual(
  source: VisualComponentSource,
  sizing: VisualSizingMode = 'bounds',
): ComponentVisualProjection {
  const backgroundColor = readStringProperty(source, 'backgroundColor');
  const color = readStringProperty(source, 'color');
  const borderColor = readStringProperty(source, 'borderColor');
  const title = readStringProperty(source, 'title');
  const tabIndex = readIntegerProperty(source, 'tabIndex');
  const style: ComponentVisualStyle = {
    width: sizing === 'fill' ? '100%' : `${String(source.bounds.width)}px`,
    height: sizing === 'fill' ? '100%' : `${String(source.bounds.height)}px`,
    ...(backgroundColor.length > 0 ? { backgroundColor } : {}),
    ...(color.length > 0 ? { color } : {}),
    ...(borderColor.length > 0
      ? { borderColor, borderStyle: 'solid' as const, borderWidth: '1px' }
      : {}),
  };

  return {
    classNames: ['wr-component', `wr-${source.type.toLowerCase()}`],
    style,
    visible: readBooleanProperty(source, 'visible', true),
    enabled: readBooleanProperty(source, 'enabled', true),
    ...(title.length > 0 ? { title } : {}),
    ...(tabIndex === undefined ? {} : { tabIndex }),
  };
}

/** Shared component styling. Hosts may override the custom properties to theme it. */
export const WEBRAD_COMPONENT_CSS = `
.wr-component { box-sizing: border-box; font: inherit; }
.wr-component[hidden] { display: none !important; }
.wr-webpage { overflow: hidden; }
.wr-weblabel { display: flex; align-items: center; color: inherit; overflow: hidden; white-space: nowrap; }
.wr-webpanel { border: 1px solid var(--wr-control-border, #677184); background: var(--wr-control-surface, #262b35); padding: 6px; overflow: hidden; }
.wr-webedit, .wr-webtextarea, .wr-webcombobox, .wr-weblistbox { border: 1px solid var(--wr-control-border, #677184); border-radius: 3px; background: var(--wr-input-bg, #11151c); color: inherit; padding: 5px 7px; outline: none; }
.wr-webedit:focus, .wr-webtextarea:focus, .wr-webcombobox:focus, .wr-weblistbox:focus { border-color: var(--wr-accent, #4da3ff); box-shadow: 0 0 0 1px var(--wr-accent, #4da3ff); }
.wr-webbutton { border: 1px solid var(--wr-control-border, #677184); border-radius: 4px; background: var(--wr-button-bg, #343b49); color: inherit; padding: 4px 12px; }
.wr-webbutton:hover:not(:disabled) { background: var(--wr-button-hover, #414a5a); }
.wr-webcheckbox { display: flex; align-items: center; gap: 7px; }
.wr-webimage { display: block; object-fit: contain; border: 1px dashed var(--wr-control-border, #677184); color: var(--wr-muted-text, #8e98aa); }
`.trim();
